result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/doccli.py", "content": "#!/usr/bin/env python3
"""doccli: render argparse-based CLI help as Markdown documentation.

Given a Python script that defines an ``argparse`` parser in a
``build_parser()`` function, doccli imports it (via importlib from a file
path), walks the parser including subparsers, and renders a Markdown
document containing:

* a summary list of commands with anchors,
* per-command usage lines,
* per-command options tables (flag, type, default, help).

Usage::

    python doccli.py path/to/tool.py -o docs.md [--prog toolname]
"""

from __future__ import annotations

import argparse
import importlib.util
import re
import sys
from pathlib import Path

__all__ = ["load_parser", "render_markdown", "main"]


# --------------------------------------------------------------------------
# Loading
# --------------------------------------------------------------------------

def load_parser(path: str | Path):
    """Import *path* and return its ``build_parser()`` result."""
    path = Path(path).resolve()
    if not path.is_file():
        raise FileNotFoundError(f"no such script: {path}")

    spec = importlib.util.spec_from_file_location(path.stem, path)
    if spec is None or spec.loader is None:
        raise ImportError(f"cannot import module from {path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)

    builder = getattr(module, "build_parser", None)
    if builder is None or not callable(builder):
        raise AttributeError(
            f"{path.name} must define a callable build_parser()"
        )
    return builder()


def _prog_name(action) -> str:
    """Best-effort display name for a subparser action's command."""
    names = [o for o in action.dest.split()] if action.dest else []
    if getattr(action, "metavar", None):
        names = [action.metavar]
    if not names:
        # fall back to option strings of the _SubParsersAction entry
        for opt in action.option_strings:
            names.append(opt.lstrip("-"))
    return " ".join(names)


def walk_parser(parser: argparse.ArgumentParser, prefix: str = ""):
    """Yield (command_path, parser) pairs, depth-first over subparsers."""
    yield prefix.rstrip(), parser
    for action in parser._actions:
        if isinstance(action, argparse._SubParsersAction):
            for name, sub in action.choices.items():
                child = f"{prefix}{name}"
                yield from walk_parser(sub, child + " " if not prefix else child + " ")


# --------------------------------------------------------------------------
# Rendering helpers
# --------------------------------------------------------------------------

def _anchor(text: str) -> str:
    """GitHub-style anchor slug for a heading."""
    text = text.strip().lower()
    text = re.sub(r"[^\w\s-]", "", text)
    return re.sub(r"[\s]+", "-", text)


def _fmt_type(parser: argparse.ArgumentParser, action) -> str:
    """Human-readable type column value for an action."""
    if isinstance(action, (argparse._HelpAction, argparse._VersionAction)):
        return ""
    if isinstance(action, argparse._StoreTrueAction):
        return "flag"
    if isinstance(action, argparse._StoreFalseAction):
        return "flag"
    if action.nargs == "+":
        base = _base_type(action)
        return f"{base} ..."
    if action.nargs == "?":
        return _base_type(action)
    if action.nargs == "*":
        return f"{_base_type(action)} ..."
    return _base_type(action)


def _base_type(action) -> str:
    if action.type is not None:
        name = getattr(action.type, "__name__", str(action.type))
        return name
    if action.choices is not None:
        return "choice"
    return "str"


def _fmt_choices(action) -> str:
    if getattr(action, "choices", None):
        return ", ".join(str(c) for c in action.choices)
    return ""


def _fmt_default(parser: argparse.ArgumentParser, action) -> str:
    if isinstance(action, (argparse._HelpAction, argparse._VersionAction)):
        return ""
    default = action.default
    if isinstance(action, argparse._StoreTrueAction):
        return "`False`"
    if isinstance(action, argparse._StoreFalseAction):
        return "`True`"
    if default is argparse.SUPPRESS:
        return ""
    if default is None:
        # positional arguments have no meaningful default
        if action.nargs == "?" or isinstance(
            action, argparse._StoreConstAction
        ) or hasattr(action, "option_strings") and action.option_strings:
            return "`None`"
        return ""
    return f"`{default!r}`"


def _flags(parser: argparse.ArgumentParser, action) -> str:
    if action.option_strings:
        return " / ".join(f"`{s}`" for s in action.option_strings)
    return f"`{action.dest}`"


def _help_text(action) -> str:
    help_ = action.help or ""
    help_ = help_.replace("|", "\\|").replace("\n", " ")
    if getattr(action, "choices", None):
        choices = ", ".join(f"`{c}`" for c in action.choices)
        sep = "; " if help_ else ""
        help_ = f"{help_}{sep}one of: {choices}"
    return help_


def _is_required(parser, action) -> bool:
    if action.required:
        return True
    return (
        not action.option_strings
        and action.nargs in (None, "+", "*")
    )


def usage_line(parser: argparse.ArgumentParser, prog: str) -> str:
    parts = [f"`{prog}`"]
    has_optional = False
    required_opts = []
    positionals = []
    sub = None
    for action in parser._actions:
        if isinstance(action, argparse._HelpAction):
            continue
        if isinstance(action, argparse._SubParsersAction):
            sub = "{" + ",".join(action.choices) + "}"
            continue
        if action.option_strings:
            if action.required:
                required_opts.append(action)
            else:
                has_optional = True
        else:
            positionals.append(action)

    for p in positionals:
        name = p.metavar or p.dest.upper()
        if p.nargs in ("*", "?"):
            parts.append(f"[{name}...]" if p.nargs == "*" else f"[{name}]")
        else:
            parts.append(name if p.nargs != "+" else f"{name} [{name}...]")

    if required_opts:
        parts.append(" ".join(a.option_strings[0] for a in required_opts))
    if has_optional:
        parts.append("[options]")
    if sub:
        parts.append(sub)
    return " ".join(parts)


def options_table(parser: argparse.ArgumentParser, prog: str) -> str:
    rows = []
    for action in parser._actions:
        if isinstance(action, argparse._HelpAction):
            continue
        if isinstance(action, argparse._SubParsersAction):
            continue  # subcommands get their own sections
        flag = _flags(parser, action)
        typ = _fmt_type(parser, action)
        default = _fmt_default(parser, action)
        help_ = _help_text(action)
        rows.append((flag, typ, default, help_))

    lines = [
        "| Option | Type | Default | Description |",
        "|--------|------|---------|-------------|",
    ]
    for flag, typ, default, help_ in rows:
        lines.append(f"| {flag} | {typ} | {default} | {help_} |")
    return "\n".join(lines)


def render_markdown(parser: argparse.ArgumentParser, prog: str) -> str:
    out: list[str] = []
    title = prog.replace("-", " ").title()
    out.append(f"# `{prog}` CLI reference")
    out.append("")
    out.append(f"Auto-generated documentation for the `{prog}` command-line tool.")
    out.append("")

    # Summary with anchors
    out.append("## Commands")
    out.append("")
    out.extend(_summary_lines(parser, prog))
    out.append("")

    # Per-command sections
    for cmd_path, p in walk_parser(parser, ""):
        heading_prog = f"{prog} {cmd_path}".strip()
        anchor = _anchor(heading_prog)
        out.append(f'<a id="{anchor}"></a>')
        out.append(f"## `{heading_prog}`")
        out.append("")
        out.append("**Usage:**")
        out.append("")
        out.append(f"    {usage_line(p, heading_prog)}")
        out.append("")
        desc = (p.description or "").strip()
        if desc:
            out.append(desc)
            out.append("")
        out.append("**Options:**")
        out.append("")
        out.append(options_table(p, heading_prog))
        out.append("")

    return "\n".join(out).rstrip() + "\n"


def _summary_lines(parser: argparse.ArgumentParser, prog: str):
    lines = []
    # root first
    lines.append(f"- [`{prog}`](#{_anchor(prog)}) — top-level")
    def rec(p, prefix):
        subs = {}
        for action in p._actions:
            if isinstance(action, argparse._SubParsersAction):
                subs = action.choices
                break
        # keep declaration order
        for action in p._actions:
            if not isinstance(action, argparse._SubParsersAction):
                continue
            for name, subp in subs.items():
                path = f"{prefix}{name}"
                full = f"{prog} {path}".strip()
                desc = (subp.description or "").strip().splitlines()[0] if subp.description else ""
                label = f"[`{full}`](#{_anchor(full)})"
                lines.append(f"- {label}" + (f" — {desc}" if desc else ""))
                rec(subp, path + " ")
    rec(parser, "")
    return lines


# --------------------------------------------------------------------------
# CLI
# --------------------------------------------------------------------------

def build_argparser() -> argparse.ArgumentParser:
    ap = argparse.ArgumentParser(
        prog="doccli", description="Render argparse CLI help as Markdown docs."
    )
    ap.add_argument("script", help="Path to a Python script defining build_parser()")
    ap.add_argument("-o", "--output", default="docs.md",
                    help="Output Markdown file (default: %(default)s)")
    ap.add_argument("--prog", default=None,
                    help="Program name used in docs (default: script stem)")
    ap.add_argument("--stdout", action="store_true",
                    help="Print Markdown to stdout instead of writing a file")
    return ap


def main(argv: list[str] | None = None) -> int:
    args = build_argparser().parse_args(argv)
    parser = load_parser(args.script)
    prog = args.prog or Path(args.script).stem
    md = render_markdown(parser, prog)
    if args.stdout:
        sys.stdout.write(md)
    else:
        Path(args.output).write_text(md, encoding="utf-8")
        print(f"wrote {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
